fun upperBound(a: ArrayList<Int>, x: Int): Int {
    if (a[0] > x) return 0
    if (back(a) <= x) return a.size
    var l = 0
    var r = a.size - 1
    while (l != r) {
        val m = (l + r) / 2
        if (a[m] > x) r = m else l = m + 1
    }
    return l
}

fun lowerBound(a: ArrayList<Int>, x: Int): Int {
    if (back(a) < x) return a.size
    var l = 0
    var r = a.size - 1
    while (l != r) {
        val m = (l + r) / 2
        if (a[m] >= x) r = m else l = m + 1
    }
    return l
}

