fun powmod(x: Long, d: Long, m: Long): Long {
    if (d == 0L) return 1
    if (d % 2 == 0L) {
        val y = powmod(x, d / 2, m)
        return (y * y) % m
    }
    return x * powmod(x, d - 1, m) % m
}

fun divup(x: Int, y: Int): Int {
    return (x + y - 1) / y
}

fun divup(x: Long, y: Long): Long {
    return (x + y - 1) / y
}

fun gcd(x: Long, y: Long): Long {
    if (x == 0L || y == 0L) return x + y
    if (x > y) return gcd(x % y, y)
    return gcd(y % x, x)
}

